import{uid as s}from"../sidebar/ui/Dom.js";export class ViewStore{constructor(s){this.store=s,this.views=[]}async load(){return this.views=await this.store.get("savedViews",[])||[],this.views}async save(){await this.store.set("savedViews",this.views)}for(s){return this.views.filter(i=>i.panel===s)}async add(i,t,e){const a={id:s("view"),panel:i,name:t,state:e,createdAt:(new Date).toISOString()};return this.views.push(a),await this.save(),a}async remove(s){const i=this.views.find(i=>i.id===s);return this.views=this.views.filter(i=>i.id!==s),await this.save(),i}async restore(s){const i=this.views.find(i=>i.id===s);return this.views=this.views.filter(i=>i.id!==s),i&&this.views.push(i),await this.save(),i}get(s){return this.views.find(i=>i.id===s)||null}}